from collections import deque

def isEscapePossible(blocked, source, target):
    if not blocked:
        return True
    blockset = {(x, y) for x, y in blocked}
    LIM = 10 ** 6
    # With B blocked cells, the largest area they can enclose is B*(B-1)/2.
    # If a BFS escapes beyond that many cells, it is not boxed in.
    threshold = len(blocked) * (len(blocked) - 1) // 2

    def bfs(s, t):
        seen = {(s[0], s[1])}
        dq = deque([(s[0], s[1])])
        while dq:
            if len(seen) > threshold:
                return True
            x, y = dq.popleft()
            for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nx, ny = x + dx, y + dy
                if 0 <= nx < LIM and 0 <= ny < LIM and (nx, ny) not in blockset and (nx, ny) not in seen:
                    if nx == t[0] and ny == t[1]:
                        return True
                    seen.add((nx, ny))
                    dq.append((nx, ny))
        return False

    return bfs(source, target) and bfs(target, source)
